<?php get_header(); while(have_posts()):the_post();?><main><section class="page-hero"><div class="wrap"><span class="eyebrow"><?php echo get_post_type()==='case_study'?'Case Study':'PA MedLog Insights';?></span><h1><?php the_title();?></h1><?php if(get_post_type()==='post'):?><p><?php echo esc_html(get_the_date('F j, Y'));?></p><?php endif;?></div></section><section class="section"><div class="wrap article-wrap"><?php if(get_post_type()==='case_study'): $fields=['challenge'=>'Challenge','solution'=>'Solution','outcomes'=>'Outcomes']; foreach($fields as $k=>$label){$v=get_post_meta(get_the_ID(),'case_'.$k,true);if($v)echo '<section class="case-section"><h2>'.esc_html($label).'</h2><p>'.nl2br(esc_html($v)).'</p></section>';} endif;?><div class="article-content"><?php the_content();?></div></div></section></main><?php endwhile;get_footer();?>
